/**
 * Left-pad a string to a minimum length.
 *
 * @param {*} str Value to convert to a string and pad.
 * @param {number} len Desired minimum length.
 * @param {string} [ch=' '] Padding character.
 * @returns {string} The padded string, or the original if it is already long enough.
