function leftPad(str, len, ch = ' ') {
  const s = String(str);
  if (s.length >= len) {
    return s;
  }
  const padLen = len - s.length;
  const padChar = ch === '' ? ' ' : String(ch).charAt(0);
  return padChar.repeat(padLen) + s;
}

